// Sink writer for the /po11y-status/notifications.json contract: dedupe
// by link, newest first, capped at 50, atomic tmp+rename. Called as a
// sub-workflow by 'HN tech news' — and reusable by any other feeder that
// passes { stories: [{ ts, title, message, status, link }] }.
const fs = require('fs');
const FILE = '/po11y-status/notifications.json';
const stories = $json.stories || [];
const existing = (() => { try { return JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch { return []; } })();
const seen = new Set(existing.map((e) => e.link));
const fresh = stories.filter((s) => s.link && s.title && !seen.has(s.link));
if (fresh.length) {
  const merged = [...fresh, ...existing].slice(0, 50);
  fs.writeFileSync(FILE + '.tmp', JSON.stringify(merged));
  fs.renameSync(FILE + '.tmp', FILE);
}
return [{ json: { added: fresh.length } }];
